using System;
using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DeepnessPresenceEffect", menuName = "Data/Battle/Effects/Enemy/DeepnessPresence Effect")]
public class DeepnessPresenceEffect : Effect
{
	private const string deepnessPresence_DCorruptionMeterID = "DeepnessPresence_DCorruptionMeter";

	private const string receiveVirtueEnemyEffectID = "ReceiveVirtueEnemyEffect";

	private const string leftmostID = "Leftmost";

	private const string rightmostID = "Rightmost";

	[Header("Action Specifics")]
	[SerializeField]
	private VortexBubbleEffect corruptedBubbleEffect;

	[Header("Rune Modifier")]
	[SerializeField]
	private GameObjectReference runesPanelGameObjectReference;

	[SerializeField]
	private BattleAction runeBattleAction;

	[SerializeField]
	private int runeActionValue;

	[Header("Description")]
	[SerializeField]
	private BattleAction onSixCorruptionAction;

	[SerializeField]
	private bool rightMost;

	[NonSerialized]
	private Rune runeToChange;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		runeToChange = null;
		RunesPanelInitializer component = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();
		component.ResetRunesToNonShuffledRunes();
		int runeRightmostEmptyIndex = GetRuneRightmostEmptyIndex(component.Runes);
		if (runeRightmostEmptyIndex != -1)
		{
			runeToChange = component.Runes[runeRightmostEmptyIndex];
			component.AddNewRune(runeBattleAction, runeActionValue, runeRightmostEmptyIndex);
		}
	}

	private int GetRuneRightmostEmptyIndex(Rune[] runes)
	{
		for (int i = 0; i < runes.Length; i++)
		{
			if (runes[i].BattleAction == null)
			{
				return i;
			}
		}
		return -1;
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return base.localizationManager.GetLocalizedAtTheStartOfTheBattle(withSpace: true) + Smart.Format(base.localizationManager.GetLocalizedString("ReceiveVirtueEnemyEffect"), runeBattleAction.GetActionName(), runeActionValue, base.localizationManager.GetLocalizedString(rightMost ? "Rightmost" : "Leftmost")) + "\n" + GetLocalizedDescription() + "\n" + base.localizationManager.GetLocalizedString("DeepnessPresence_DCorruptionMeter") + base.localizationManager.GetLocalizedSpace() + onSixCorruptionAction.GetActionDescription(1).LowercaseFirst();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerCorruptionStats>().CurrentCorruption == 6f)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().AddEffect(corruptedBubbleEffect, 1);
			effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		}
		return effectAmount;
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (runeToChange != null)
		{
			RunesPanelInitializer component = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();
			int replaceRuneIndex = -1;
			Rune[] runes = component.Runes;
			for (int num = runes.Length - 1; num >= 0; num--)
			{
				if (runes[num].BattleAction == runeBattleAction)
				{
					replaceRuneIndex = num;
					break;
				}
			}
			component.ReplaceRuneWithNewRune(null, 0, replaceRuneIndex, dontModifyNonShuffledRunes: true);
			int index = -1;
			Rune[] nonShuffledRunes = component.PlayerCurrentRunes.NonShuffledRunes;
			for (int num2 = nonShuffledRunes.Length - 1; num2 >= 0; num2--)
			{
				if (nonShuffledRunes[num2].BattleAction == runeBattleAction)
				{
					index = num2;
					break;
				}
			}
			component.SetRuneNonShuffledRunes(null, 0, index);
		}
		return effectAmount;
	}
}
